// UI-local model for the ICP form. This is deliberately not the shared data
// contract: once src/core/types.ts is agreed, the accepted IcpDraft gets mapped
// onto it before anything is handed to the agent pipeline.

export const COMPANY_SIZE_OPTIONS = [
  { value: "1-10", label: "1–10 employees" },
  { value: "11-50", label: "11–50 employees" },
  { value: "51-200", label: "51–200 employees" },
  { value: "201-500", label: "201–500 employees" },
  { value: "501-1000", label: "501–1,000 employees" },
  { value: "1001-5000", label: "1,001–5,000 employees" },
  { value: "5001+", label: "5,001+ employees" },
] as const;

export type CompanySize = (typeof COMPANY_SIZE_OPTIONS)[number]["value"];

export const INDUSTRY_SUGGESTIONS = [
  "Software / SaaS",
  "Fintech",
  "Cybersecurity",
  "Healthcare technology",
  "E-commerce",
  "Logistics and supply chain",
  "Marketing technology",
  "Manufacturing",
];

export const ICP_LIMITS = {
  industryMaxLength: 120,
  maxLocations: 10,
  maxKeywords: 15,
  maxExcludedDomains: 50,
} as const;

export type IcpFormValues = {
  industry: string;
  companySize: string;
  location: string;
  keywords: string;
  excludedDomains: string;
  mode: string;
};

export type IcpField = keyof IcpFormValues;

export type IcpFieldErrors = Partial<Record<IcpField, string>>;

export type IcpDraft = {
  industry: string;
  companySize: CompanySize;
  locations: string[];
  keywords: string[];
  excludedDomains: string[];
  // Live Crustdata mode is not available until server-side access control exists.
  mode: "synthetic";
};

export type IcpFormState =
  | { status: "idle"; values: IcpFormValues }
  | {
      status: "invalid";
      values: IcpFormValues;
      errors: IcpFieldErrors;
      message: string;
    }
  | { status: "accepted"; values: IcpFormValues; icp: IcpDraft };

export const EMPTY_ICP_FORM: IcpFormValues = {
  industry: "",
  companySize: "",
  location: "",
  keywords: "",
  excludedDomains: "",
  mode: "synthetic",
};

export const INITIAL_ICP_FORM_STATE: IcpFormState = {
  status: "idle",
  values: EMPTY_ICP_FORM,
};

const DOMAIN_PATTERN =
  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

function readString(formData: FormData, name: IcpField): string {
  const value = formData.get(name);
  return typeof value === "string" ? value.trim() : "";
}

export function readIcpFormValues(formData: FormData): IcpFormValues {
  return {
    industry: readString(formData, "industry"),
    companySize: readString(formData, "companySize"),
    location: readString(formData, "location"),
    keywords: readString(formData, "keywords"),
    excludedDomains: readString(formData, "excludedDomains"),
    mode: readString(formData, "mode"),
  };
}

// Splits comma- or newline-separated input and drops blanks and
// case-insensitive duplicates, keeping the first spelling.
export function splitList(raw: string): string[] {
  const seen = new Set<string>();
  const items: string[] = [];
  for (const part of raw.split(/[,\n]/)) {
    const item = part.trim();
    const key = item.toLowerCase();
    if (item && !seen.has(key)) {
      seen.add(key);
      items.push(item);
    }
  }
  return items;
}

// Accepts pasted URLs as well as bare domains: "https://www.Acme.com/about"
// becomes "acme.com".
export function normalizeDomain(raw: string): string {
  const host = raw
    .trim()
    .toLowerCase()
    .replace(/^[a-z][a-z0-9+.-]*:\/\//, "")
    .split(/[/?#]/)[0];
  return host.replace(/:\d+$/, "").replace(/\.$/, "").replace(/^www\./, "");
}

export function validateIcpForm(
  values: IcpFormValues,
): { ok: true; icp: IcpDraft } | { ok: false; errors: IcpFieldErrors } {
  const errors: IcpFieldErrors = {};

  if (!values.industry) {
    errors.industry = "Enter a target industry.";
  } else if (values.industry.length > ICP_LIMITS.industryMaxLength) {
    errors.industry = `Keep the industry under ${ICP_LIMITS.industryMaxLength} characters.`;
  }

  const size = COMPANY_SIZE_OPTIONS.find(
    (option) => option.value === values.companySize,
  );
  if (!size) {
    errors.companySize = "Choose a company size.";
  }

  const locations = splitList(values.location);
  if (locations.length > ICP_LIMITS.maxLocations) {
    errors.location = `Use at most ${ICP_LIMITS.maxLocations} locations.`;
  }

  const keywords = splitList(values.keywords);
  if (keywords.length > ICP_LIMITS.maxKeywords) {
    errors.keywords = `Use at most ${ICP_LIMITS.maxKeywords} keywords.`;
  }

  const excludedDomains = [
    ...new Set(splitList(values.excludedDomains).map(normalizeDomain)),
  ].filter(Boolean);
  const invalidDomains = excludedDomains.filter(
    (domain) => !DOMAIN_PATTERN.test(domain),
  );
  if (invalidDomains.length > 0) {
    errors.excludedDomains = `Not a valid domain: ${invalidDomains.slice(0, 3).join(", ")}${invalidDomains.length > 3 ? "…" : ""}`;
  } else if (excludedDomains.length > ICP_LIMITS.maxExcludedDomains) {
    errors.excludedDomains = `Use at most ${ICP_LIMITS.maxExcludedDomains} excluded domains.`;
  }

  if (values.mode !== "synthetic") {
    errors.mode = "Live Crustdata mode is not available yet. Use synthetic data.";
  }

  if (!size || Object.keys(errors).length > 0) {
    return { ok: false, errors };
  }

  return {
    ok: true,
    icp: {
      industry: values.industry,
      companySize: size.value,
      locations,
      keywords,
      excludedDomains,
      mode: "synthetic",
    },
  };
}

export function companySizeLabel(size: CompanySize): string {
  return (
    COMPANY_SIZE_OPTIONS.find((option) => option.value === size)?.label ?? size
  );
}

"use server";

import {
  readIcpFormValues,
  validateIcpForm,
  type IcpFormState,
} from "./_lib/icp-form";

// Server Actions are reachable by direct POST, so the ICP is validated here
// even though the form also guides the user. The agent pipeline is not
// connected yet: an accepted ICP is only echoed back to the results area, and
// nothing here calls Crustdata.
export async function submitIcp(
  _prevState: IcpFormState,
  formData: FormData,
): Promise<IcpFormState> {
  const values = readIcpFormValues(formData);
  const result = validateIcpForm(values);

  if (!result.ok) {
    return {
      status: "invalid",
      values,
      errors: result.errors,
      message: "Check the highlighted fields and try again.",
    };
  }

  return { status: "accepted", values, icp: result.icp };
}

import type { ReactNode } from "react";

type FormFieldProps = {
  id: string;
  label: string;
  hint?: string;
  error?: string;
  optional?: boolean;
  children: ReactNode;
};

export function fieldDescriptionIds(id: string, hint?: string, error?: string) {
  const ids = [hint && `${id}-hint`, error && `${id}-error`].filter(Boolean);
  return ids.length > 0 ? ids.join(" ") : undefined;
}

export function inputClassName(hasError: boolean) {
  return [
    "block w-full rounded-lg border bg-white px-3 py-2 text-sm text-slate-900 shadow-xs",
    "placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-offset-0",
    "dark:bg-slate-900 dark:text-slate-100 dark:placeholder:text-slate-500",
    hasError
      ? "border-red-400 focus:border-red-500 focus:ring-red-500/30 dark:border-red-500/70"
      : "border-slate-300 focus:border-indigo-500 focus:ring-indigo-500/30 dark:border-slate-700",
  ].join(" ");
}

export function FormField({
  id,
  label,
  hint,
  error,
  optional,
  children,
}: FormFieldProps) {
  return (
    <div className="flex flex-col gap-1.5">
      <label
        htmlFor={id}
        className="flex items-baseline justify-between gap-2 text-sm font-medium text-slate-800 dark:text-slate-200"
      >
        {label}
        {optional && (
          <span className="text-xs font-normal text-slate-500 dark:text-slate-400">
            Optional
          </span>
        )}
      </label>
      {children}
      {hint && !error && (
        <p id={`${id}-hint`} className="text-xs text-slate-500 dark:text-slate-400">
          {hint}
        </p>
      )}
      {error && (
        <p id={`${id}-error`} className="text-xs font-medium text-red-600 dark:text-red-400">
          {error}
        </p>
      )}
    </div>
  );
}

import type { InputHTMLAttributes } from "react";
import { FormField, fieldDescriptionIds, inputClassName } from "./FormField";

type TextFieldProps = Omit<InputHTMLAttributes<HTMLInputElement>, "id" | "name"> & {
  name: string;
  label: string;
  hint?: string;
  error?: string;
  optional?: boolean;
};

export function TextField({
  name,
  label,
  hint,
  error,
  optional,
  ...inputProps
}: TextFieldProps) {
  const id = `field-${name}`;
  return (
    <FormField id={id} label={label} hint={hint} error={error} optional={optional}>
      <input
        id={id}
        name={name}
        type="text"
        aria-invalid={error ? true : undefined}
        aria-describedby={fieldDescriptionIds(id, hint, error)}
        className={inputClassName(Boolean(error))}
        {...inputProps}
      />
    </FormField>
  );
}

import type { TextareaHTMLAttributes } from "react";
import { FormField, fieldDescriptionIds, inputClassName } from "./FormField";

type TextAreaFieldProps = Omit<
  TextareaHTMLAttributes<HTMLTextAreaElement>,
  "id" | "name"
> & {
  name: string;
  label: string;
  hint?: string;
  error?: string;
  optional?: boolean;
};

export function TextAreaField({
  name,
  label,
  hint,
  error,
  optional,
  rows = 3,
  ...textareaProps
}: TextAreaFieldProps) {
  const id = `field-${name}`;
  return (
    <FormField id={id} label={label} hint={hint} error={error} optional={optional}>
      <textarea
        id={id}
        name={name}
        rows={rows}
        aria-invalid={error ? true : undefined}
        aria-describedby={fieldDescriptionIds(id, hint, error)}
        className={`${inputClassName(Boolean(error))} resize-y`}
        {...textareaProps}
      />
    </FormField>
  );
}

import type { SelectHTMLAttributes } from "react";
import { FormField, fieldDescriptionIds, inputClassName } from "./FormField";

type SelectOption = { value: string; label: string };

type SelectFieldProps = Omit<
  SelectHTMLAttributes<HTMLSelectElement>,
  "id" | "name" | "children"
> & {
  name: string;
  label: string;
  options: readonly SelectOption[];
  placeholder?: string;
  hint?: string;
  error?: string;
  optional?: boolean;
};

export function SelectField({
  name,
  label,
  options,
  placeholder,
  hint,
  error,
  optional,
  ...selectProps
}: SelectFieldProps) {
  const id = `field-${name}`;
  return (
    <FormField id={id} label={label} hint={hint} error={error} optional={optional}>
      <select
        id={id}
        name={name}
        aria-invalid={error ? true : undefined}
        aria-describedby={fieldDescriptionIds(id, hint, error)}
        className={inputClassName(Boolean(error))}
        {...selectProps}
      >
        {placeholder && (
          <option value="" disabled>
            {placeholder}
          </option>
        )}
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </FormField>
  );
}

type DataModeSelectorProps = {
  defaultValue: string;
  error?: string;
};

// Synthetic data is the only selectable mode. The live option is shown for
// context but stays disabled; the Server Action also rejects it, so enabling
// the radio in the browser does not unlock paid Crustdata calls.
export function DataModeSelector({ defaultValue, error }: DataModeSelectorProps) {
  return (
    <fieldset
      className="flex flex-col gap-2"
      aria-describedby={error ? "field-mode-error" : undefined}
    >
      <legend className="mb-1.5 text-sm font-medium text-slate-800 dark:text-slate-200">
        Data source
      </legend>

      <label className="flex cursor-pointer gap-3 rounded-lg border border-slate-300 bg-white p-3 has-checked:border-indigo-500 has-checked:bg-indigo-50/60 has-checked:ring-1 has-checked:ring-indigo-500 dark:border-slate-700 dark:bg-slate-900 dark:has-checked:bg-indigo-500/10">
        <input
          type="radio"
          name="mode"
          value="synthetic"
          defaultChecked={defaultValue !== "live"}
          className="mt-0.5 accent-indigo-600"
        />
        <span className="flex flex-col gap-0.5">
          <span className="text-sm font-medium text-slate-900 dark:text-slate-100">
            Synthetic data
          </span>
          <span className="text-xs text-slate-500 dark:text-slate-400">
            Generated demo companies. No API calls and no credits spent.
          </span>
        </span>
      </label>

      <label className="flex cursor-not-allowed gap-3 rounded-lg border border-dashed border-slate-300 p-3 opacity-60 dark:border-slate-700">
        <input
          type="radio"
          name="mode"
          value="live"
          disabled
          className="mt-0.5"
        />
        <span className="flex flex-col gap-0.5">
          <span className="text-sm font-medium text-slate-900 dark:text-slate-100">
            Live Crustdata
          </span>
          <span className="text-xs text-slate-500 dark:text-slate-400">
            Uses paid credits. Requires operator access and is not enabled in
            this build.
          </span>
        </span>
      </label>

      {error && (
        <p id="field-mode-error" className="text-xs font-medium text-red-600 dark:text-red-400">
          {error}
        </p>
      )}
    </fieldset>
  );
}

import {
  COMPANY_SIZE_OPTIONS,
  ICP_LIMITS,
  INDUSTRY_SUGGESTIONS,
  type IcpFormState,
} from "../_lib/icp-form";
import { DataModeSelector } from "./form/DataModeSelector";
import { SelectField } from "./form/SelectField";
import { TextAreaField } from "./form/TextAreaField";
import { TextField } from "./form/TextField";

type IcpFormProps = {
  action: (formData: FormData) => void;
  state: IcpFormState;
  pending: boolean;
};

export function IcpForm({ action, state, pending }: IcpFormProps) {
  const { values } = state;
  const errors = state.status === "invalid" ? state.errors : {};

  return (
    <form
      action={action}
      noValidate
      aria-labelledby="icp-form-title"
      className="flex flex-col gap-5 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6 dark:border-slate-800 dark:bg-slate-900/60"
    >
      <div className="flex flex-col gap-1">
        <h2
          id="icp-form-title"
          className="text-base font-semibold text-slate-900 dark:text-slate-100"
        >
          Ideal customer profile
        </h2>
        <p className="text-sm text-slate-500 dark:text-slate-400">
          Describe the companies you want to find. Separate multiple values with
          commas or new lines.
        </p>
      </div>

      <TextField
        name="industry"
        label="Target industry"
        placeholder="e.g. Software / SaaS"
        list="industry-suggestions"
        maxLength={ICP_LIMITS.industryMaxLength}
        autoComplete="off"
        required
        defaultValue={values.industry}
        error={errors.industry}
      />
      <datalist id="industry-suggestions">
        {INDUSTRY_SUGGESTIONS.map((industry) => (
          <option key={industry} value={industry} />
        ))}
      </datalist>

      <SelectField
        name="companySize"
        label="Company size"
        placeholder="Select a headcount range"
        options={COMPANY_SIZE_OPTIONS}
        required
        defaultValue={values.companySize}
        error={errors.companySize}
      />

      <TextField
        name="location"
        label="Location"
        placeholder="e.g. United Kingdom, Germany"
        hint="Countries or regions. Leave blank for any location."
        optional
        autoComplete="off"
        defaultValue={values.location}
        error={errors.location}
      />

      <TextAreaField
        name="keywords"
        label="Target company keywords"
        placeholder="e.g. payments API, compliance automation"
        hint="Products, technologies or themes the company should match."
        optional
        defaultValue={values.keywords}
        error={errors.keywords}
      />

      <TextAreaField
        name="excludedDomains"
        label="Excluded domains"
        placeholder={"e.g. competitor.com\nexisting-customer.io"}
        hint="Companies to skip, such as current customers or competitors."
        optional
        spellCheck={false}
        defaultValue={values.excludedDomains}
        error={errors.excludedDomains}
      />

      <DataModeSelector defaultValue={values.mode} error={errors.mode} />

      {state.status === "invalid" && (
        <p
          role="alert"
          className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700 dark:bg-red-500/10 dark:text-red-300"
        >
          {state.message}
        </p>
      )}

      <button
        type="submit"
        disabled={pending}
        className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-indigo-600 px-4 text-sm font-semibold text-white shadow-sm transition-colors hover:bg-indigo-500 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600 disabled:cursor-wait disabled:opacity-70"
      >
        {pending && (
          <span
            aria-hidden="true"
            className="size-4 animate-spin rounded-full border-2 border-white/40 border-t-white"
          />
        )}
        {pending ? "Checking profile…" : "Find prospects"}
      </button>
    </form>
  );
}

import type { ReactNode } from "react";

type PanelProps = {
  title: string;
  description?: string;
  badge?: ReactNode;
  className?: string;
  children: ReactNode;
};

export function Panel({ title, description, badge, className, children }: PanelProps) {
  const headingId = `panel-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  return (
    <section
      aria-labelledby={headingId}
      className={`flex flex-col gap-4 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900/60 ${className ?? ""}`}
