// Measure the layout inside iframes at each width, using the same production page.
const widths = [1280, 1024, 820, 375];
const measure = (w) => new Promise((resolve) => {
  const f = document.createElement('iframe');
  f.style.cssText = `position:absolute;left:-9999px;top:0;width:${w}px;height:900px;border:0`;
  f.src = location.href;
  f.onload = () => setTimeout(() => {
    const d = f.contentDocument;
    const r = (s) => { const b = d.querySelector(s).getBoundingClientRect(); return `${Math.round(b.x)}+${Math.round(b.width)}`; };
    const res = 'section[aria-labelledby=results-title]';
    const cols = (el) => d.defaultView.getComputedStyle(el).gridTemplateColumns.split(' ').length;
    const out = { w, main: r('main'), form: r('form'), results: r(res),
      side_by_side: d.querySelector('form').getBoundingClientRect().top === d.querySelector(res).getBoundingClientRect().top || Math.abs(d.querySelector('form').getBoundingClientRect().top - d.querySelector(res).getBoundingClientRect().top) < 5,
      stats: cols(d.querySelector(res + ' > .grid')), evBudget: cols(d.querySelector('#panel-evidence').closest('.grid')),
      pageScroll: d.documentElement.scrollWidth > d.documentElement.clientWidth };
    f.remove(); resolve(out);
  }, 600);
  document.body.appendChild(f);
});
const results = [];
for (const w of widths) results.push(await measure(w));
