1	// Deterministic CompanyProvider backed by the synthetic fixtures. No network.
2	
3	import { FIXTURE_COMPANIES } from "../fixtures/companies";
4	import type { RawCompany, RunConfig } from "../types";
5	import { normalizeLinkedInUrl } from "./normalize";
6	import {
7	  BudgetGuard,
8	  type CompanyProvider,
9	  type ProviderErrorCategory,
10	  type ProviderResult,
11	  type SearchFilters,
12	} from "./provider";
13	
14	// Make the Nth call (1-based, counted across all three methods) fail.
15	export interface InjectedFailure {
16	  readonly call_number: number;
17	  readonly category: ProviderErrorCategory;
18	  readonly message?: string;
19	}
20	
21	export interface FixtureProviderOptions {
22	  readonly config: Pick<RunConfig, "max_search_results" | "max_enrichments">;
23	  // Cost of each call: a fixed amount, or a function of the 1-based call
24	  // number. Default 0.
25	  readonly cost_usd?: number | ((call_number: number) => number);
26	  readonly failures?: readonly InjectedFailure[];
27	  // Defaults to the synthetic fixtures.
28	  readonly companies?: readonly RawCompany[];
29	}
30	
31	export class FixtureProvider implements CompanyProvider {
32	  readonly budget: BudgetGuard;
33	  private readonly cost_usd: number | ((call_number: number) => number);
34	  private readonly failures: readonly InjectedFailure[];
35	  private readonly companies: readonly RawCompany[];
36	  private call_count = 0;
37	
38	  constructor(options: FixtureProviderOptions) {
39	    this.budget = new BudgetGuard(options.config);
40	    this.cost_usd = options.cost_usd ?? 0;
41	    this.failures = options.failures ?? [];
42	    this.companies = options.companies ?? FIXTURE_COMPANIES;
43	  }
44	
45	  // Number of calls made so far, including failed ones.
46	  get calls_made(): number {
47	    return this.call_count;
48	  }
49	
50	  private nextCall(): { n: number; cost: number; failure?: InjectedFailure } {
51	    this.call_count += 1;
52	    const n = this.call_count;
53	    const cost = typeof this.cost_usd === "function" ? this.cost_usd(n) : this.cost_usd;
54	    return { n, cost, failure: this.failures.find((f) => f.call_number === n) };
55	  }
56	
57	  async autocompleteIndustry(query: string): Promise<ProviderResult<readonly string[]>> {
58	    const { failure } = this.nextCall();
59	    if (failure) return fail(failure.category, failure.message);
60	    const q = query.trim().toLowerCase();
61	    const matches = [
62	      ...new Set(this.companies.map((c) => c.industry).filter((i) => i !== "")),
63	    ].filter((i) => i.toLowerCase().includes(q));
64	    if (q === "" || matches.length === 0) {
65	      return fail("no_match", `no industry matches "${query}"`);
66	    }
67	    // Autocomplete is free and outside the search/enrich caps.
68	    return { ok: true, data: matches, cost_usd: 0, calls: 1 };
69	  }
70	
71	  async searchCompanies(
72	    filters: SearchFilters,
73	    limit: number,
74	  ): Promise<ProviderResult<readonly RawCompany[]>> {
75	    if (!this.budget.canSearch(limit)) {
76	      return fail("budget_cap_reached", "search cap would be exceeded");
77	    }
78	    const { cost, failure } = this.nextCall();
79	    if (failure) return fail(failure.category, failure.message);
80	    const industries = filters.industries.map((i) => i.toLowerCase());
81	    const found = this.companies
82	      .filter((c) => {
83	        if (industries.length > 0 && !industries.includes(c.industry.toLowerCase())) {
84	          return false;
85	        }
86	        if (
87	          filters.employee_count_ranges.length > 0 &&
88	          !filters.employee_count_ranges.includes(c.employee_count_range)
89	        ) {
90	          return false;
91	        }
92	        // Records with no location pass: the fixtures rarely carry one.
93	        const country = c.location?.country;
94	        return !country || !filters.country || country.toLowerCase() === filters.country.toLowerCase();
95	      })
96	      .slice(0, limit)
97	      .map((c): RawCompany => ({ ...c, source: "search" }));
98	    if (found.length === 0) return fail("no_match", "no companies match the filters");
99	    this.budget.recordSearch(found.length, cost);
100	    return { ok: true, data: found, cost_usd: cost, calls: 1 };
101	  }
102	
103	  async enrichCompanies(
104	    linkedin_urls: readonly string[],
105	  ): Promise<ProviderResult<readonly RawCompany[]>> {
106	    if (!this.budget.canEnrich(linkedin_urls.length)) {
107	      return fail("budget_cap_reached", "enrichment cap would be exceeded");
108	    }
109	    const { cost, failure } = this.nextCall();
110	    if (failure) return fail(failure.category, failure.message);
111	    const wanted = new Set(linkedin_urls.map(normalizeLinkedInUrl));
112	    const found = this.companies.filter(
113	      (c) => c.professional_network_url !== "" && wanted.has(normalizeLinkedInUrl(c.professional_network_url)),
114	    );
115	    // Unmatched URLs are simply absent from data; if none match, no_match.
116	    if (found.length === 0) return fail("no_match", "no fixture matches the LinkedIn URLs");
117	    this.budget.recordEnrich(found.length, cost);
118	    return { ok: true, data: found, cost_usd: cost, calls: 1 };
119	  }
120	}
121	
122	function fail(category: ProviderErrorCategory, message?: string): ProviderResult<never> {
123	  return { ok: false, error: { category, message: message ?? category } };
124	}
