1	// Builds facts from a raw company. Pure and deterministic: no network, no
2	// randomness, no mutation of the inputs. Statuses are set here by code only;
3	// this module never creates a fact with provider "model".
4	
5	import type {
6	  AnyFact,
7	  Fact,
8	  FactSource,
9	  RawCompany,
10	  Validation,
11	  ValidationIssue,
12	} from "../types";
13	import { normalizeDomain } from "./normalize";
14	import { parseEmployeeRange } from "./validation";
15	
16	type CrustProvider = "crustdata" | "fixture";
17	
18	// Issue codes that make the fact on the issue's field uncertain.
19	const UNCERTAIN_CODES: ReadonlySet<string> = new Set([
20	  "junk_website",
21	  "size_headcount_mismatch",
22	]);
23	
24	const SIZE_FIELDS: readonly string[] = [
25	  "employee_count_range",
26	  "latest_headcount",
27	  "revenue_range",
28	];
29	
30	function nonEmptyText(value: unknown): value is string {
31	  return typeof value === "string" && value.trim() !== "";
32	}
33	
34	function finiteNumber(value: unknown): value is number {
35	  return typeof value === "number" && Number.isFinite(value);
36	}
37	
38	export function buildFacts(
39	  raw: RawCompany,
40	  validation: Validation,
41	  provider: CrustProvider,
42	): readonly AnyFact[] {
43	  if (validation.status === "rejected") return [];
44	
45	  const recordId = String(raw.crustdata_company_id);
46	  const source: FactSource = {
47	    provider,
48	    operation: raw.source === "enrich" ? "company_enrich" : "company_search",
49	    record_id: recordId,
50	    retrieved_at: raw.retrieved_at,
51	  };
52	
53	  // field -> why it is uncertain. A size mismatch means the size facts
54	  // contradict each other and we cannot tell which is wrong, so all of them
55	  // are marked, not only the field the rule looked at.
56	  const uncertainReason = new Map<string, string>();
57	  for (const issue of validation.issues) {
58	    if (!UNCERTAIN_CODES.has(issue.code)) continue;
59	    if (issue.code === "size_headcount_mismatch") {
60	      const reason = `${issue.reason} The size facts contradict each other, so none of them can be trusted.`;
61	      for (const field of SIZE_FIELDS) {
62	        if (!uncertainReason.has(field)) uncertainReason.set(field, reason);
63	      }
64	    } else if (!uncertainReason.has(issue.field)) {
65	      uncertainReason.set(issue.field, issue.reason);
66	    }
67	  }
68	
69	  const facts: AnyFact[] = [];
70	  const byField = new Map<string, AnyFact>();
71	
72	  const add = (field: string, value: unknown, claim: string): void => {
73	    const reason = uncertainReason.get(field);
74	    const fact: Fact<unknown> = {
75	      id: `${recordId}:${field}`,
76	      value,
77	      claim: reason ? `${claim} (uncertain: ${reason})` : claim,
78	      field,
79	      source,
80	      status: reason ? "uncertain" : "given",
81	    };
82	    facts.push(fact);
83	    byField.set(field, fact);
84	  };
85	
86	  const text = (field: string, value: unknown, label: string): void => {
87	    if (nonEmptyText(value)) add(field, value, `${label} is ${value}`);
88	  };
89	
90	  text("name", raw.name, "Company name");
91	  text("primary_domain", raw.primary_domain, "Primary domain");
92	  text("website", raw.website, "Website");
93	  text(
94	    "professional_network_url",
95	    raw.professional_network_url,
96	    "LinkedIn page",
97	  );
98	  text("employee_count_range", raw.employee_count_range, "Employee count range");
99	  text("industry", raw.industry, "Industry");
100	  text("description", raw.description, "Description");
101	
102	  if (finiteNumber(raw.founded_year)) {
103	    add("founded_year", raw.founded_year, `Founded in ${raw.founded_year}`);
104	  }
105	  text("legal_type", raw.legal_type, "Legal type");
106	  if (finiteNumber(raw.latest_headcount) && raw.latest_headcount > 0) {
107	    add(
108	      "latest_headcount",
109	      raw.latest_headcount,
110	      `Latest headcount is ${raw.latest_headcount}`,
111	    );
112	  }
113	  text("revenue_range", raw.revenue_range, "Revenue range");
114	  text("location.country", raw.location?.country, "Country");
115	  text("location.city", raw.location?.city, "City");
116	
117	  if (Array.isArray(raw.specialities)) {
118	    const list = raw.specialities.filter(nonEmptyText);
119	    if (list.length > 0) {
120	      add("specialities", list, `Specialities are ${list.join(", ")}`);
121	    }
122	  }
123	  if (finiteNumber(raw.linkedin_followers)) {
124	    add(
125	      "linkedin_followers",
126	      raw.linkedin_followers,
127	      `Has ${raw.linkedin_followers} LinkedIn followers`,
128	    );
129	  }
130	
131	  // Derived cross-checks: two independent, non-uncertain facts that agree.
132	  const usable = (field: string): AnyFact | undefined => {
133	    const f = byField.get(field);
134	    return f && f.status === "given" ? f : undefined;
135	  };
136	  const derivedSource: FactSource = {
137	    provider: "derived",
138	    retrieved_at: raw.retrieved_at,
139	  };
140	
141	  const website = usable("website");
142	  const domain = usable("primary_domain");
143	  if (website && domain) {
144	    const host = normalizeDomain(String(website.value));
145	    if (host !== "" && host === normalizeDomain(String(domain.value))) {
146	      facts.push({
147	        id: `${recordId}:xcheck:website_domain`,
148	        value: host,
149	        claim: `Website host matches the primary domain (${host})`,
150	        field: "website_domain",
151	        source: derivedSource,
152	        status: "cross_checked",
