23	// Above this implied revenue per employee (USD) the data is not believable.
24	export const MAX_REVENUE_PER_EMPLOYEE_USD = 500000;
25	
26	interface Range {
27	  readonly min: number;
28	  readonly max: number; // Infinity for open-ended ranges like "10,001+"
29	}
30	
31	function toNumber(text: string): number | undefined {
32	  const n = Number(text.replace(/,/g, ""));
33	  return Number.isFinite(n) ? n : undefined;
34	}
35	
36	// "51-200" -> {51, 200}; "10,001+" -> {10001, Infinity}; else undefined.
37	export function parseEmployeeRange(input: unknown): Range | undefined {
38	  if (typeof input !== "string") return undefined;
39	  const s = input.trim();
40	  const span = /^(\d[\d,]*)\s*[-–]\s*(\d[\d,]*)$/.exec(s);
41	  if (span) {
42	    const min = toNumber(span[1]);
43	    const max = toNumber(span[2]);
44	    if (min === undefined || max === undefined || max < min) return undefined;
45	    return { min, max };
46	  }
47	  const open = /^(\d[\d,]*)\s*\+$/.exec(s);
48	  if (open) {
49	    const min = toNumber(open[1]);
50	    return min === undefined ? undefined : { min, max: Infinity };
51	  }
52	  return undefined;
53	}
54	
55	const SUFFIX: Readonly<Record<string, number>> = {
56	  "": 1,
57	  k: 1e3,
58	  m: 1e6,
59	  b: 1e9,
60	};
61	
62	// Lower bound in USD of a range like "$10M-$50M", "$500K-$1M" or "$10M+".
63	// Undefined for anything else (e.g. "<$1M", "unknown").
64	export function parseRevenueLowerBound(input: unknown): number | undefined {
65	  if (typeof input !== "string") return undefined;
66	  const m = /^\$?\s*(\d[\d,]*(?:\.\d+)?)\s*([kmb]?)\s*(?:[-–]|to\b|\+|$)/i.exec(
67	    input.trim(),
68	  );
69	  if (!m) return undefined;
70	  const base = toNumber(m[1]);
71	  if (base === undefined) return undefined;
72	  return base * (SUFFIX[m[2].toLowerCase()] ?? 1);
73	}
74	
75	function isEmpty(value: unknown): boolean {
76	  return typeof value !== "string" || value.trim() === "";
77	}
78	
79	function isJunkHost(host: string): boolean {
80	  return JUNK_HOSTS.some((j) => host === j || host.endsWith(`.${j}`));
81	}
82	
83	// Key used to group duplicates: domain first, LinkedIn URL when no domain.
84	function duplicateKey(raw: RawCompany): string | undefined {
85	  const domain = normalizeDomain(raw.primary_domain);
86	  if (domain) return `domain:${domain}`;
87	  const linkedin = normalizeLinkedInUrl(raw.professional_network_url);
88	  if (linkedin) return `linkedin:${linkedin}`;
89	  return undefined;
90	}
91	
92	function sizeIssues(raw: RawCompany): ValidationIssue[] {
93	  const issues: ValidationIssue[] = [];
94	  const headcount = raw.latest_headcount;
95	  if (
96	    typeof headcount !== "number" ||
97	    !Number.isFinite(headcount) ||
98	    headcount <= 0
99	  ) {
100	    return issues;
101	  }
102	
103	  const range = parseEmployeeRange(raw.employee_count_range);
104	  if (range && (headcount < range.min || headcount > range.max)) {
105	    issues.push({
106	      code: "size_headcount_mismatch",
107	      field: "latest_headcount",
108	      reason: `Headcount ${headcount} is outside the listed size range "${raw.employee_count_range}".`,
109	    });
110	  }
111	
112	  const revenueMin = parseRevenueLowerBound(raw.revenue_range);
113	  if (
114	    revenueMin !== undefined &&
115	    revenueMin / headcount > MAX_REVENUE_PER_EMPLOYEE_USD
116	  ) {
117	    issues.push({
118	      code: "size_headcount_mismatch",
119	      field: "revenue_range",
120	      reason: `Revenue "${raw.revenue_range}" with ${headcount} employees implies more than $${MAX_REVENUE_PER_EMPLOYEE_USD.toLocaleString("en-US")} per employee, which is implausible.`,
121	    });
122	  }
123	  return issues;
124	}
