126	export function validateCompanies(
127	  raws: readonly RawCompany[],
128	): readonly Validation[] {
129	  const firstSeen = new Map<string, number>(); // key -> crustdata_company_id
130	
131	  return raws.map((raw): Validation => {
132	    const issues: ValidationIssue[] = [];
133	
134	    const noName = isEmpty(raw.name);
135	    const domain = normalizeDomain(raw.primary_domain ?? "");
136	    const linkedin = normalizeLinkedInUrl(raw.professional_network_url ?? "");
137	
138	    if (noName) {
139	      issues.push({
140	        code: "missing_name",
141	        field: "name",
142	        reason: "The company has no name.",
143	      });
144	    }
145	    if (!domain) {
146	      issues.push({
147	        code: "missing_domain",
148	        field: "primary_domain",
149	        reason: "The company has no primary domain.",
150	      });
151	    }
152	
153	    const host = normalizeDomain(raw.website ?? "");
154	    if (host && isJunkHost(host)) {
155	      issues.push({
156	        code: "junk_website",
157	        field: "website",
158	        reason: `The website points to ${host}, a messaging, link-shortener or social page rather than a company site.`,
159	      });
160	    }
161	
162	    if (!linkedin) {
163	      issues.push({
164	        code: "missing_linkedin",
165	        field: "professional_network_url",
166	        reason: "The company has no LinkedIn page.",
167	      });
168	    }
169	
170	    let isLaterDuplicate = false;
171	    const key = duplicateKey(raw);
172	    if (key !== undefined) {
173	      const keptId = firstSeen.get(key);
174	      if (keptId === undefined) {
175	        firstSeen.set(key, raw.crustdata_company_id);
176	      } else {
177	        isLaterDuplicate = true;
178	        const viaDomain = key.startsWith("domain:");
179	        issues.push({
180	          code: "duplicate_domain",
181	          field: viaDomain ? "primary_domain" : "professional_network_url",
182	          reason: viaDomain
183	            ? `Another company (id ${keptId}) already uses the domain ${domain}.`
184	            : `Another company (id ${keptId}) already uses the LinkedIn page ${linkedin}.`,
185	          related_company_id: keptId,
186	        });
187	      }
188	    }
189	
190	    issues.push(...sizeIssues(raw));
191	
192	    let status: ValidationStatus;
193	    if ((noName && !domain && !linkedin) || isLaterDuplicate) {
194	      status = "rejected";
195	    } else if (issues.length > 0) {
196	      status = "flagged";
197	    } else {
198	      status = "valid";
199	    }
200	    return { status, issues };
201	  });
202	}
