// Tracing seam for the agent pipeline. The pipeline only talks to this
// interface; neatlogs-tracer.ts adapts it to the neatlogs SDK and tests use an
// in-memory recorder. Plain TypeScript only.

// Span kinds the pipeline uses. Each is a valid neatlogs trace() kind.
export type PipelineSpanKind = "WORKFLOW" | "CHAIN" | "TOOL" | "AGENT" | "LLM";

export type TraceAttributeValue =
  | string
  | number
  | boolean
  | readonly string[]
  | readonly number[];

export type TraceAttributes = Readonly<Record<string, TraceAttributeValue>>;

export interface PipelineSpan {
  setAttributes(attributes: TraceAttributes): void;
  addEvent(name: string, attributes?: TraceAttributes): void;
}

export interface PipelineSpanOptions {
  readonly name: string;
  readonly kind: PipelineSpanKind;
  // Captured as the span input. Keep it serialisable.
  readonly input?: unknown;
  readonly attributes?: TraceAttributes;
}

export interface PipelineTracer {
  span<T>(
    options: PipelineSpanOptions,
    fn: (span: PipelineSpan) => Promise<T>,
  ): Promise<T>;
}

const NOOP_SPAN: PipelineSpan = {
  setAttributes() {},
  addEvent() {},
};

export const noopTracer: PipelineTracer = {
  span: (_options, fn) => fn(NOOP_SPAN),
};

// Adapts PipelineTracer to the neatlogs SDK. Entry points must call
// initTracing() from src/core/observability/tracing.ts first (and
// closeTracing() in scripts); without it neatlogs records nothing.

import { trace } from "neatlogs";
import type {
  PipelineSpan,
  PipelineTracer,
  TraceAttributes,
} from "./tracer";

type OtelSpan = Parameters<Parameters<typeof trace>[1]>[0];
type OtelAttributes = Parameters<OtelSpan["setAttributes"]>[0];

// OpenTelemetry attribute arrays are mutable; copy readonly arrays.
function toOtelAttributes(attributes: TraceAttributes): OtelAttributes {
  const out: OtelAttributes = {};
  for (const [key, value] of Object.entries(attributes)) {
    out[key] = Array.isArray(value) ? [...value] : value;
  }
  return out;
}

export const neatlogsTracer: PipelineTracer = {
  span(options, fn) {
    return trace(
      { name: options.name, kind: options.kind, input: options.input },
      async (otelSpan) => {
        const span: PipelineSpan = {
          setAttributes: (attributes) =>
            otelSpan.setAttributes(toOtelAttributes(attributes)),
          addEvent: (name, attributes) =>
            otelSpan.addEvent(
              name,
              attributes ? toOtelAttributes(attributes) : undefined,
            ),
        };
        if (options.attributes) span.setAttributes(options.attributes);
        return fn(span);
      },
    );
  },
};

// Model access for the agent. The pipeline only talks to LlmClient; the real
// adapter lives in openai-llm.ts and tests use fake-llm.ts. Like providers,
// clients return errors instead of throwing.

export interface LlmMessage {
  readonly role: "system" | "user";
  readonly content: string;
}

export interface LlmRequest {
  // Always RunConfig.model; never hardcoded by a client.
  readonly model: string;
  readonly messages: readonly LlmMessage[];
  // Always RunConfig.max_output_tokens_per_call.
  readonly max_output_tokens: number;
}

export type LlmResponse =
  | {
      readonly ok: true;
      readonly text: string;
      readonly input_tokens: number;
      readonly output_tokens: number;
      // True when the model stopped because it hit max_output_tokens.
      readonly truncated: boolean;
      // US dollars, when the client knows it. Undefined otherwise.
      readonly cost_usd?: number;
    }
  | { readonly ok: false; readonly error: { readonly message: string } };

export interface LlmClient {
  complete(request: LlmRequest): Promise<LlmResponse>;
}

// Real LlmClient over the OpenAI SDK, for an OpenAI-compatible endpoint such
// as the LiteLLM gateway. The caller builds the OpenAI client (base URL and
// key come from the environment at the entry point, never from here).

import type OpenAI from "openai";
import type { LlmClient, LlmRequest, LlmResponse } from "./llm";

export class OpenAiCompatibleLlmClient implements LlmClient {
  private readonly client: Pick<OpenAI, "chat">;

  constructor(client: Pick<OpenAI, "chat">) {
    this.client = client;
  }

  async complete(request: LlmRequest): Promise<LlmResponse> {
    try {
      const completion = await this.client.chat.completions.create({
        model: request.model,
        messages: request.messages.map((m) => ({
          role: m.role,
          content: m.content,
        })),
        // max_tokens rather than max_completion_tokens: it is the parameter
        // OpenAI-compatible gateways accept most widely.
        max_tokens: request.max_output_tokens,
      });
      const choice = completion.choices[0];
      return {
        ok: true,
        text: choice?.message.content ?? "",
        input_tokens: completion.usage?.prompt_tokens ?? 0,
        output_tokens: completion.usage?.completion_tokens ?? 0,
        truncated: choice?.finish_reason === "length",
      };
    } catch (err) {
      return {
        ok: false,
        error: { message: err instanceof Error ? err.message : String(err) },
      };
    }
  }
}

// Deterministic LlmClient for tests and synthetic demos. No network. By
// default it answers every request with a well-formed assessment for the
// company named in the prompt.

import type { LlmClient, LlmRequest, LlmResponse } from "./llm";

export type FakeLlmReply =
  | string
  | {
      readonly text: string;
      readonly input_tokens?: number;
      readonly output_tokens?: number;
      readonly truncated?: boolean;
      readonly cost_usd?: number;
    }
  | { readonly error: string };

// call_number is 1-based.
export type FakeLlmResponder = (
  request: LlmRequest,
  call_number: number,
) => FakeLlmReply;

export interface FakeLlmClientOptions {
  readonly respond?: FakeLlmResponder;
  // Simulated latency per call, to let tests observe overlapping calls.
  readonly delay_ms?: number;
}

export class FakeLlmClient implements LlmClient {
  readonly requests: LlmRequest[] = [];
  private readonly respond: FakeLlmResponder;
  private readonly delay_ms: number;
  private in_flight = 0;
  private max_in_flight_seen = 0;

  constructor(options: FakeLlmClientOptions = {}) {
    this.respond = options.respond ?? defaultFakeAssessment;
    this.delay_ms = options.delay_ms ?? 0;
  }

  // Most calls that were ever running at the same time.
  get max_in_flight(): number {
    return this.max_in_flight_seen;
  }

  async complete(request: LlmRequest): Promise<LlmResponse> {
    this.requests.push(request);
    const call_number = this.requests.length;
    this.in_flight += 1;
    this.max_in_flight_seen = Math.max(this.max_in_flight_seen, this.in_flight);
    try {
      if (this.delay_ms > 0) {
        await new Promise((resolve) => setTimeout(resolve, this.delay_ms));
      }
      const reply = this.respond(request, call_number);
      if (typeof reply === "string") {
        return { ok: true, text: reply, input_tokens: 100, output_tokens: 50, truncated: false };
      }
      if ("error" in reply) {
        return { ok: false, error: { message: reply.error } };
      }
      return {
        ok: true,
        text: reply.text,
        input_tokens: reply.input_tokens ?? 100,
        output_tokens: reply.output_tokens ?? 50,
        truncated: reply.truncated ?? false,
        cost_usd: reply.cost_usd,
      };
    } finally {
      this.in_flight -= 1;
    }
  }
}

// Reads the company id from the prompt's JSON record and returns a stable
// assessment for it.
export function defaultFakeAssessment(request: LlmRequest): string {
  const prompt = request.messages.map((m) => m.content).join("\n");
  const id = Number(/"crustdata_company_id":\s*(\d+)/.exec(prompt)?.[1] ?? 0);
  return JSON.stringify({
    fit_score: 40 + (id % 50),
    criterion_scores: [
      { criterion: "Industry", score: 60 + (id % 40), fact_ids: [`${id}:industry`] },
    ],
    uncertainty_notes: ["Synthetic assessment from the fake model client."],
    outreach: {
      body: `Hello from SignalScout. We work with teams like yours (company ${id}).`,
      cited_fact_ids: [`${id}:name`],
    },
  });
}

// Agent-local types for the naive baseline pipeline. These are not part of
// the shared contract in src/core/types.ts; they cover what the baseline has
// and nothing more (no validation, no facts).

import type {
  BudgetSnapshot,
  CompanyProvider,
  ProviderErrorCategory,
  SearchFilters,
} from "../data/provider";
import type { Assessment, RawCompany, Run, RunConfig, RunStep } from "../types";
import type { LlmClient } from "./llm";
import type { PipelineTracer } from "./tracer";

// What the user asked for. Built by the app from its form.
export interface IcpInput {
  // Free text; mapped to provider industry labels via autocomplete.
  readonly industry: string;
  // Provider range strings, e.g. "51-200". Empty means any size.
  readonly employee_count_ranges: readonly string[];
  // Countries. SearchFilters takes one, so only the first is searched.
  readonly locations: readonly string[];
  // Given to the model only; the provider has no keyword filter.
  readonly keywords: readonly string[];
  // Given to the model only; the baseline does not filter on them.
  readonly excluded_domains: readonly string[];
}

export type EnrichmentStatus =
  | "enriched" // returned by the enrich call
  | "not_returned" // requested, but missing from the response
  | "skipped_budget" // not requested, or refused, because of the enrichment cap
  | "skipped_no_linkedin" // no LinkedIn URL, so it cannot be enriched
  | "failed"; // the enrich call failed

export interface EnrichmentOutcome {
  readonly status: EnrichmentStatus;
  // Set when the enrich call returned an error.
  readonly error_category?: ProviderErrorCategory;
}

export type AssessmentOutcome =
  | { readonly status: "assessed"; readonly assessment: Assessment }
  | {
      readonly status: "failed";
      readonly reason: "llm_error" | "malformed_output" | "truncated";
      readonly message: string;
    }
  | {
      readonly status: "not_assessed";
      readonly reason: "llm_call_cap" | "not_enriched";
    };

// One company in the baseline result. Deliberately not the shared Prospect:
// the baseline has no validation or facts, and faking them would hide that.
export interface BaselineProspect {
  // The enriched record when enrichment returned it, else the search record.
  readonly raw: RawCompany;
  readonly enrichment: EnrichmentOutcome;
  readonly assessment: AssessmentOutcome;
}

export type PipelineIssueCode =
  | "industry_not_recognised"
  | "industry_autocomplete_failed"
  | "extra_locations_ignored"
  | "search_budget_exhausted"
  | "search_no_match"
  | "search_failed"
  | "enrich_budget_exhausted"
  | "enrich_no_results"
  | "enrich_partial"
  | "enrich_failed"
  | "llm_call_cap_reached";

// A run-level note or failure. Per-company problems live on the prospect.
export interface PipelineIssue {
  readonly step: RunStep;
  readonly code: PipelineIssueCode;
  readonly message: string;
  readonly error_category?: ProviderErrorCategory;
}

// completed_empty: the search found nothing. stopped: search failed, so the
// run could not continue.
export type PipelineStatus = "completed" | "completed_empty" | "stopped";

export interface PipelineResult {
  readonly status: PipelineStatus;
  readonly run: Run;
  readonly filters: SearchFilters;
  readonly prospects: readonly BaselineProspect[];
  readonly issues: readonly PipelineIssue[];
  readonly usage: {
    readonly provider: BudgetSnapshot;
    readonly max_search_results: number;
    readonly max_enrichments: number;
    readonly llm_calls: number;
    readonly max_llm_calls_per_run: number;
  };
}

export interface PipelineDeps {
  readonly provider: CompanyProvider;
  // The BudgetGuard the provider enforces, read to size enrich requests.
  // CompanyProvider does not expose one, so it is passed separately (for a
  // FixtureProvider, pass provider.budget).
  readonly budget: { snapshot(): BudgetSnapshot };
  readonly llm: LlmClient;
  readonly tracer?: PipelineTracer;
  // Defaults to a random UUID.
  readonly trace_id?: string;
  // Milliseconds clock for step timings. Defaults to Date.now.
  readonly now?: () => number;
}

export interface PipelineOptions {
  // Defaults to DEV_RUN_CONFIG.
  readonly config?: RunConfig;
  // Which companies go to the model. Defaults to every searched company, so
  // the baseline trace shows what happens with unenriched and junk records.
  readonly assess?: "all_searched" | "enriched_only";
}

// Turns the user's ICP into provider SearchFilters, a plain-English
// description for the Run record, and the criteria the model scores against.

import type { CompanyProvider, SearchFilters } from "../data/provider";
import type { IcpInput, PipelineIssue } from "./types";

export interface SearchPlan {
  readonly filters: SearchFilters;
  readonly issues: readonly PipelineIssue[];
  readonly cost_usd: number;
  readonly calls: number;
}

// Free text like "software" becomes the provider's own labels via the free
// autocomplete call. If autocomplete fails, the raw text is searched as-is.
export async function buildSearchFilters(
  icp: IcpInput,
  provider: CompanyProvider,
): Promise<SearchPlan> {
  const issues: PipelineIssue[] = [];
  let industries: readonly string[] = [];
  let cost_usd = 0;
  let calls = 0;

  const industry = icp.industry.trim();
  if (industry !== "") {
    const result = await provider.autocompleteIndustry(industry);
    if (result.ok) {
      industries = result.data;
      cost_usd += result.cost_usd;
      calls += result.calls;
    } else {
      industries = [industry];
      issues.push(
        result.error.category === "no_match"
          ? {
              step: "plan",
              code: "industry_not_recognised",
              message: `No provider industry matches "${industry}"; searching the text as given.`,
              error_category: "no_match",
            }
          : {
              step: "plan",
              code: "industry_autocomplete_failed",
              message: `Industry autocomplete failed (${result.error.message}); searching "${industry}" as given.`,
              error_category: result.error.category,
            },
      );
    }
  }

  const locations = icp.locations.map((l) => l.trim()).filter((l) => l !== "");
  if (locations.length > 1) {
    issues.push({
      step: "plan",
      code: "extra_locations_ignored",
      message: `Search takes one country; using "${locations[0]}" and ignoring ${locations.slice(1).join(", ")}.`,
    });
  }

  return {
    filters: {
      country: locations[0] ?? "",
      industries,
      employee_count_ranges: icp.employee_count_ranges,
    },
    issues,
    cost_usd,
    calls,
  };
}

export function describeIcp(icp: IcpInput): string {
  const parts = [
    `Companies in ${icp.industry.trim() || "any industry"}`,
    icp.employee_count_ranges.length > 0
      ? `with ${icp.employee_count_ranges.join(" or ")} employees`
      : "of any size",
    icp.locations.length > 0 ? `located in ${icp.locations.join(", ")}` : "in any location",
  ];
  let text = parts.join(" ");
  if (icp.keywords.length > 0) text += `, matching: ${icp.keywords.join(", ")}`;
  if (icp.excluded_domains.length > 0) {
    text += `, excluding: ${icp.excluded_domains.join(", ")}`;
  }
  return `${text}.`;
}

// One criterion per part of the ICP the user actually filled in.
export function assessmentCriteria(icp: IcpInput): readonly string[] {
  const criteria: string[] = [];
  if (icp.industry.trim() !== "") criteria.push(`Industry: ${icp.industry.trim()}`);
  if (icp.employee_count_ranges.length > 0) {
    criteria.push(`Company size: ${icp.employee_count_ranges.join(" or ")} employees`);
  }
  if (icp.locations.length > 0) criteria.push(`Location: ${icp.locations.join(", ")}`);
  if (icp.keywords.length > 0) criteria.push(`Keywords: ${icp.keywords.join(", ")}`);
  return criteria;
}

// Enriches searched companies in search order, within the enrichment cap.
// Naive on purpose: no ranking, no duplicate checks, one batch call.

import { normalizeLinkedInUrl } from "../data/normalize";
import type { CompanyProvider } from "../data/provider";
import type { RawCompany } from "../types";
import type { EnrichmentOutcome, PipelineIssue } from "./types";

export interface EnrichStepResult {
  // Index-aligned with the searched companies.
  readonly outcomes: readonly EnrichmentOutcome[];
  // Searched-company index -> the enriched record for it.
  readonly enriched: ReadonlyMap<number, RawCompany>;
  readonly issues: readonly PipelineIssue[];
  readonly requested: number;
  readonly cost_usd: number;
  readonly calls: number;
}

export async function enrichInSearchOrder(
  companies: readonly RawCompany[],
  provider: CompanyProvider,
  remaining_enrichments: number,
): Promise<EnrichStepResult> {
  const outcomes: EnrichmentOutcome[] = companies.map((c) => ({
    status:
      c.professional_network_url.trim() === "" ? "skipped_no_linkedin" : "skipped_budget",
  }));
  const enriched = new Map<number, RawCompany>();
  const issues: PipelineIssue[] = [];

  const candidates = companies
    .map((c, i) => i)
    .filter((i) => outcomes[i].status !== "skipped_no_linkedin");
  // BudgetGuard refuses a whole call that asks for more than the cap allows,
  // so ask only for what is left.
  const selected = candidates.slice(0, Math.max(0, remaining_enrichments));

  if (selected.length === 0) {
    if (candidates.length > 0) {
      issues.push({
        step: "enrich",
        code: "enrich_budget_exhausted",
        message: "No enrichments left in this run's budget.",
      });
    }
    return { outcomes, enriched, issues, requested: 0, cost_usd: 0, calls: 0 };
  }

  const result = await provider.enrichCompanies(
    selected.map((i) => companies[i].professional_network_url),
  );

  if (!result.ok) {
    const category = result.error.category;
    const status =
      category === "budget_cap_reached"
        ? "skipped_budget"
        : category === "no_match"
          ? "not_returned"
          : "failed";
    for (const i of selected) outcomes[i] = { status, error_category: category };
    issues.push({
      step: "enrich",
      code:
        category === "budget_cap_reached"
          ? "enrich_budget_exhausted"
          : category === "no_match"
            ? "enrich_no_results"
            : "enrich_failed",
      message: `Enrichment of ${selected.length} companies returned ${category}: ${result.error.message}`,
      error_category: category,
    });
    return { outcomes, enriched, issues, requested: selected.length, cost_usd: 0, calls: 0 };
  }

  // Match each request to a returned record by id, then by LinkedIn URL.
  const byId = new Map(result.data.map((r) => [r.crustdata_company_id, r]));
  const byUrl = new Map(
    result.data
      .filter((r) => r.professional_network_url !== "")
      .map((r) => [normalizeLinkedInUrl(r.professional_network_url), r]),
  );
  let missing = 0;
  for (const i of selected) {
    const company = companies[i];
    const match =
      byId.get(company.crustdata_company_id) ??
      byUrl.get(normalizeLinkedInUrl(company.professional_network_url));
    if (match) {
      outcomes[i] = { status: "enriched" };
      enriched.set(i, match);
    } else {
      outcomes[i] = { status: "not_returned" };
      missing += 1;
    }
  }
  if (missing > 0) {
    issues.push({
      step: "enrich",
      code: "enrich_partial",
      message: `${missing} of ${selected.length} requested companies were not returned by enrichment.`,
    });
  }

  return {
    outcomes,
    enriched,
    issues,
    requested: selected.length,
    cost_usd: result.cost_usd,
    calls: result.calls,
  };
}

// Builds the assessment prompt and parses the model's reply into the shared
// Assessment shape. The parse checks structure only, so the result can be
// typed; judging the content (score ranges, cited fact ids) is the job of
// validateAssessment() and checkClaims(), which the baseline does not run.

import type { Assessment, CriterionScore, OutreachDraft } from "../types";
import type { LlmMessage } from "./llm";
import type { BaselineProspect, IcpInput } from "./types";

const SYSTEM_PROMPT = `You are SignalScout, a B2B prospect qualification assistant.
Assess how well one company fits the user's ideal customer profile and draft a short first outreach message.

Reply with one JSON object and nothing else, in exactly this shape:
{
  "fit_score": <integer 0-100>,
  "criterion_scores": [
    { "criterion": "<one of the listed criteria>", "score": <integer 0-100>, "fact_ids": ["<fact id>"] }
  ],
  "uncertainty_notes": ["<anything you could not confirm>"],
  "outreach": { "body": "<message under 120 words>", "cited_fact_ids": ["<fact id>"] }
}

A fact id is "<crustdata_company_id>:<field>", naming a field present in the company record, e.g. "1001:industry".
Omit "outreach" if the record gives you nothing specific to say.`;

export function buildAssessmentMessages(
  icp_description: string,
  criteria: readonly string[],
  icp: IcpInput,
  prospect: Pick<BaselineProspect, "raw" | "enrichment">,
): readonly LlmMessage[] {
  const lines = [
    `Ideal customer profile: ${icp_description}`,
    `Criteria to score:\n${criteria.length > 0 ? criteria.map((c) => `- ${c}`).join("\n") : "- Overall fit"}`,
  ];
  if (icp.excluded_domains.length > 0) {
    lines.push(`The user wants to exclude these domains: ${icp.excluded_domains.join(", ")}`);
  }
  lines.push(
    `Enrichment status: ${prospect.enrichment.status}`,
    `Company record (JSON):\n${JSON.stringify(prospect.raw, null, 2)}`,
  );
  return [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: lines.join("\n\n") },
  ];
}

export type ParsedAssessment =
  | { readonly ok: true; readonly assessment: Assessment }
  | { readonly ok: false; readonly message: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((v) => typeof v === "string");
}

// Models often wrap JSON in a ```json fence; accept that, nothing looser.
function stripCodeFence(text: string): string {
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(text.trim());
  return fenced ? fenced[1] : text.trim();
}

export function parseAssessment(text: string): ParsedAssessment {
  let data: unknown;
  try {
    data = JSON.parse(stripCodeFence(text));
  } catch {
    return { ok: false, message: "Model output is not valid JSON." };
  }
  if (!isRecord(data)) return { ok: false, message: "Model output is not a JSON object." };

  if (!isFiniteNumber(data.fit_score)) {
    return { ok: false, message: "fit_score is missing or not a number." };
  }
  if (!Array.isArray(data.criterion_scores)) {
    return { ok: false, message: "criterion_scores is missing or not an array." };
  }
  const criterion_scores: CriterionScore[] = [];
  for (const item of data.criterion_scores) {
    if (
      !isRecord(item) ||
      typeof item.criterion !== "string" ||
      !isFiniteNumber(item.score) ||
      !isStringArray(item.fact_ids)
    ) {
      return { ok: false, message: "A criterion score is not { criterion, score, fact_ids }." };
    }
    criterion_scores.push({
      criterion: item.criterion,
      score: item.score,
      fact_ids: item.fact_ids,
    });
  }
  if (!isStringArray(data.uncertainty_notes)) {
    return { ok: false, message: "uncertainty_notes is missing or not a list of strings." };
  }

  let outreach: OutreachDraft | undefined;
  if (data.outreach !== undefined && data.outreach !== null) {
    if (
      !isRecord(data.outreach) ||
      typeof data.outreach.body !== "string" ||
      !isStringArray(data.outreach.cited_fact_ids)
    ) {
      return { ok: false, message: "outreach is not { body, cited_fact_ids }." };
    }
    outreach = { body: data.outreach.body, cited_fact_ids: data.outreach.cited_fact_ids };
  }

  return {
    ok: true,
    assessment: {
      fit_score: data.fit_score,
      criterion_scores,
      uncertainty_notes: data.uncertainty_notes,
      ...(outreach ? { outreach } : {}),
    },
  };
}

// Accumulates the per-step counts, costs and timings that make up a Run.

import type { Run, RunConfig, RunStep } from "../types";

const STEPS: readonly RunStep[] = ["plan", "search", "validate", "enrich", "assess"];

function zeroByStep(): Record<RunStep, number> {
  return Object.fromEntries(STEPS.map((s) => [s, 0])) as Record<RunStep, number>;
}

export class RunRecorder {
  readonly counts = {
    searched: 0,
    enriched: 0,
    delivered: 0,
    llm_calls: 0,
    llm_input_tokens: 0,
    llm_output_tokens: 0,
  };
  private readonly costs = zeroByStep();
  private readonly timings = zeroByStep();
  private readonly now: () => number;

  constructor(now: () => number) {
    this.now = now;
  }

  async time<T>(step: RunStep, fn: () => Promise<T>): Promise<T> {
    const start = this.now();
    try {
      return await fn();
    } finally {
      this.timings[step] += this.now() - start;
    }
  }

  addCost(step: RunStep, cost_usd: number): void {
    this.costs[step] += cost_usd;
  }

  build(trace_id: string, input_description: string, config: RunConfig): Run {
    return {
      trace_id,
      input_description,
      config,
      counts: { ...this.counts },
      cost_usd_by_step: { ...this.costs },
      timings_ms_by_step: { ...this.timings },
    };
  }
}

// Naive baseline pipeline: plan -> search -> enrich -> assess. It deliberately
// skips validation, deduplication, buildFacts(), validateAssessment() and
// checkClaims(), so its trace shows what the unguarded agent does.
// No network of its own: data comes from the CompanyProvider and model output
// from the LlmClient passed in.

import type { SearchFilters } from "../data/provider";
import { DEV_RUN_CONFIG, type RawCompany } from "../types";
import { buildAssessmentMessages, parseAssessment } from "./assess";
import { enrichInSearchOrder } from "./enrich";
import { assessmentCriteria, buildSearchFilters, describeIcp } from "./icp";
import type { LlmResponse } from "./llm";
import { RunRecorder } from "./recorder";
import { noopTracer } from "./tracer";
import type {
  AssessmentOutcome,
  BaselineProspect,
  EnrichmentOutcome,
  IcpInput,
  PipelineDeps,
  PipelineIssue,
  PipelineOptions,
  PipelineResult,
  PipelineStatus,
} from "./types";

type SearchOutcome =
  | { readonly kind: "found"; readonly companies: readonly RawCompany[] }
  | { readonly kind: "empty" }
  | { readonly kind: "stopped" };

export async function runBaselinePipeline(
  icp: IcpInput,
  deps: PipelineDeps,
  options: PipelineOptions = {},
): Promise<PipelineResult> {
  const config = options.config ?? DEV_RUN_CONFIG;
  const assessScope = options.assess ?? "all_searched";
  const tracer = deps.tracer ?? noopTracer;
  const trace_id = deps.trace_id ?? crypto.randomUUID();
  const recorder = new RunRecorder(deps.now ?? Date.now);
  const input_description = describeIcp(icp);
  const issues: PipelineIssue[] = [];

  return tracer.span(
    {
      name: "signalscout_baseline_run",
      kind: "WORKFLOW",
      input: { trace_id, icp },
      attributes: {
        "signalscout.trace_id": trace_id,
        "signalscout.pipeline": "naive_baseline",
        "signalscout.model": config.model,
        "signalscout.max_search_results": config.max_search_results,
        "signalscout.max_enrichments": config.max_enrichments,
        "signalscout.max_llm_calls_per_run": config.max_llm_calls_per_run,
        "signalscout.max_output_tokens_per_call": config.max_output_tokens_per_call,
      },
    },
    async (root) => {
      const finish = (
        status: PipelineStatus,
        filters: SearchFilters,
        prospects: readonly BaselineProspect[],
      ): PipelineResult => {
        recorder.counts.delivered = prospects.length;
        const run = recorder.build(trace_id, input_description, config);
        const provider = deps.budget.snapshot();
        root.setAttributes({
          "signalscout.status": status,
          "signalscout.searched": run.counts.searched,
          "signalscout.enriched": run.counts.enriched,
          "signalscout.delivered": run.counts.delivered,
          "signalscout.llm_calls": run.counts.llm_calls,
          "signalscout.provider_cost_usd": provider.cost_usd,
          "signalscout.issue_codes": issues.map((i) => i.code),
        });
        return {
          status,
          run,
          filters,
          prospects,
          issues,
          usage: {
            provider,
            max_search_results: config.max_search_results,
            max_enrichments: config.max_enrichments,
            llm_calls: run.counts.llm_calls,
            max_llm_calls_per_run: config.max_llm_calls_per_run,
          },
        };
      };

      // 1. Plan: ICP -> SearchFilters (free industry autocomplete).
      const plan = await recorder.time("plan", () =>
        tracer.span({ name: "plan", kind: "CHAIN", input: icp }, async (span) => {
          const result = await buildSearchFilters(icp, deps.provider);
          span.setAttributes({
            "search.industries": result.filters.industries,
            "search.country": result.filters.country,
            "search.employee_count_ranges": result.filters.employee_count_ranges,
          });
          return result;
        }),
      );
      recorder.addCost("plan", plan.cost_usd);
      issues.push(...plan.issues);
      const filters = plan.filters;

      // 2. Search.
      const search = await recorder.time("search", () =>
        tracer.span(
          { name: "search", kind: "TOOL", input: filters },
          async (span): Promise<SearchOutcome> => {
            const limit = config.max_search_results - deps.budget.snapshot().searched;
            if (limit <= 0) {
              issues.push({
                step: "search",
                code: "search_budget_exhausted",
                message: "No search results left in this run's budget.",
              });
              span.setAttributes({ "provider.outcome": "budget_exhausted" });
              return { kind: "stopped" };
            }
            const result = await deps.provider.searchCompanies(filters, limit);
            if (result.ok) {
              recorder.addCost("search", result.cost_usd);
              recorder.counts.searched = result.data.length;
              span.setAttributes({
                "provider.outcome": "ok",
                "provider.limit": limit,
                "provider.returned": result.data.length,
                "provider.cost_usd": result.cost_usd,
                "provider.calls": result.calls,
              });
              return { kind: "found", companies: result.data };
            }
            const category = result.error.category;
            span.setAttributes({ "provider.outcome": category, "provider.limit": limit });
            if (category === "no_match") {
              issues.push({
                step: "search",
                code: "search_no_match",
                message: "No companies match the search filters.",
                error_category: category,
              });
              return { kind: "empty" };
            }
            issues.push({
              step: "search",
              code: category === "budget_cap_reached" ? "search_budget_exhausted" : "search_failed",
              message: `Search failed with ${category}: ${result.error.message}`,
              error_category: category,
            });
            return { kind: "stopped" };
          },
        ),
      );
      if (search.kind === "stopped") return finish("stopped", filters, []);
      if (search.kind === "empty") return finish("completed_empty", filters, []);
      const companies = search.companies;

      // 3. Enrich in search order, within the remaining enrichment budget.
      const enrich = await recorder.time("enrich", () =>
        tracer.span(
          {
            name: "enrich",
            kind: "TOOL",
            input: { companies: companies.map((c) => c.crustdata_company_id) },
          },
          async (span) => {
            const remaining = config.max_enrichments - deps.budget.snapshot().enriched;
            const result = await enrichInSearchOrder(companies, deps.provider, remaining);
            const statusCount = (status: EnrichmentOutcome["status"]) =>
              result.outcomes.filter((o) => o.status === status).length;
            span.setAttributes({
              "enrich.remaining_before": Math.max(0, remaining),
              "enrich.requested": result.requested,
              "enrich.enriched": statusCount("enriched"),
              "enrich.not_returned": statusCount("not_returned"),
              "enrich.skipped_budget": statusCount("skipped_budget"),
              "enrich.skipped_no_linkedin": statusCount("skipped_no_linkedin"),
              "enrich.failed": statusCount("failed"),
              "provider.cost_usd": result.cost_usd,
            });
            return result;
          },
        ),
      );
      recorder.addCost("enrich", enrich.cost_usd);
      recorder.counts.enriched = enrich.enriched.size;
      issues.push(...enrich.issues);

      const pending = companies.map((company, i) => ({
        raw: enrich.enriched.get(i) ?? company,
        enrichment: enrich.outcomes[i],
      }));

      // 4. Assess, one company at a time, within the model-call cap.
      const criteria = assessmentCriteria(icp);
      const prospects = await recorder.time("assess", () =>
        tracer.span(
          { name: "assess", kind: "AGENT", input: { companies: pending.length, criteria } },
          async (span) => {
            const out: BaselineProspect[] = [];
            let capReached = false;
            // Sequential on purpose: no parallel model calls.
            for (const prospect of pending) {
              if (assessScope === "enriched_only" && prospect.enrichment.status !== "enriched") {
                out.push({ ...prospect, assessment: { status: "not_assessed", reason: "not_enriched" } });
                continue;
              }
              if (recorder.counts.llm_calls >= config.max_llm_calls_per_run) {
                capReached = true;
                out.push({ ...prospect, assessment: { status: "not_assessed", reason: "llm_call_cap" } });
                continue;
              }
              const assessment = await assessOne(prospect);
              out.push({ ...prospect, assessment });
            }
            if (capReached) {
              issues.push({
                step: "assess",
                code: "llm_call_cap_reached",
                message: `Stopped assessing after ${config.max_llm_calls_per_run} model calls.`,
              });
            }
            span.setAttributes({
              "llm.calls": recorder.counts.llm_calls,
              "llm.input_tokens": recorder.counts.llm_input_tokens,
              "llm.output_tokens": recorder.counts.llm_output_tokens,
              "assess.assessed": out.filter((p) => p.assessment.status === "assessed").length,
              "assess.failed": out.filter((p) => p.assessment.status === "failed").length,
              "assess.not_assessed": out.filter((p) => p.assessment.status === "not_assessed").length,
            });
            return out;
          },
        ),
      );

      return finish("completed", filters, prospects);

      async function assessOne(
        prospect: Pick<BaselineProspect, "raw" | "enrichment">,
      ): Promise<AssessmentOutcome> {
        const messages = buildAssessmentMessages(input_description, criteria, icp, prospect);
        return tracer.span(
          {
            name: "assess_company",
            kind: "LLM",
            input: messages,
            attributes: {
              "company.id": prospect.raw.crustdata_company_id,
              "company.enrichment_status": prospect.enrichment.status,
              "llm.model": config.model,
              "llm.max_output_tokens": config.max_output_tokens_per_call,
            },
          },
          async (span) => {
            recorder.counts.llm_calls += 1;
            let response: LlmResponse;
            try {
              response = await deps.llm.complete({
                model: config.model,
                messages,
                max_output_tokens: config.max_output_tokens_per_call,
              });
            } catch (err) {
              // Clients should not throw; guard anyway so one company cannot end the run.
              response = {
                ok: false,
                error: { message: err instanceof Error ? err.message : String(err) },
              };
            }

            if (!response.ok) {
              span.setAttributes({ "assess.outcome": "llm_error" });
              return { status: "failed", reason: "llm_error", message: response.error.message };
            }
            recorder.counts.llm_input_tokens += response.input_tokens;
            recorder.counts.llm_output_tokens += response.output_tokens;
            if (response.cost_usd !== undefined) recorder.addCost("assess", response.cost_usd);
            span.setAttributes({
              "llm.input_tokens": response.input_tokens,
              "llm.output_tokens": response.output_tokens,
              "llm.truncated": response.truncated,
              "llm.output": response.text,
            });

            if (response.truncated) {
              span.setAttributes({ "assess.outcome": "truncated" });
              return {
                status: "failed",
                reason: "truncated",
                message: `Model output hit the ${config.max_output_tokens_per_call}-token limit.`,
              };
            }
            const parsed = parseAssessment(response.text);
            span.setAttributes({ "assess.outcome": parsed.ok ? "assessed" : "malformed_output" });
            return parsed.ok
              ? { status: "assessed", assessment: parsed.assessment }
              : { status: "failed", reason: "malformed_output", message: parsed.message };
          },
        );
      }
    },
  );
}

