// Test doubles for the agent pipeline. No network: data comes from the
// synthetic fixtures and model output from FakeLlmClient.

import type { FakeLlmClientOptions } from "../../src/core/agent/fake-llm";
import { FakeLlmClient } from "../../src/core/agent/fake-llm";
import type {
  PipelineSpan,
  PipelineTracer,
  TraceAttributeValue,
} from "../../src/core/agent/tracer";
import type { IcpInput, PipelineDeps } from "../../src/core/agent/types";
import {
  FixtureProvider,
  type FixtureProviderOptions,
} from "../../src/core/data/fixture-provider";
import type {
  CompanyProvider,
  ProviderResult,
  SearchFilters,
} from "../../src/core/data/provider";
import type { RawCompany, RunConfig } from "../../src/core/types";

// Matches every fixture: no industry, size or location filter.
export const OPEN_ICP: IcpInput = {
  industry: "",
  employee_count_ranges: [],
  locations: [],
  keywords: [],
  excluded_domains: [],
};

export function icp(overrides: Partial<IcpInput>): IcpInput {
  return { ...OPEN_ICP, ...overrides };
}

export interface RecordedSpan {
  readonly name: string;
  readonly kind: string;
  readonly input: unknown;
  readonly attributes: Record<string, TraceAttributeValue>;
  readonly events: { name: string; attributes?: Record<string, TraceAttributeValue> }[];
  readonly children: RecordedSpan[];
}

// In-memory tracer that keeps the span tree. Relies on spans running one at a
// time, which the pipeline guarantees.
export function createRecordingTracer(): { tracer: PipelineTracer; roots: RecordedSpan[] } {
  const roots: RecordedSpan[] = [];
  const stack: RecordedSpan[] = [];
  const tracer: PipelineTracer = {
    async span(options, fn) {
      const recorded: RecordedSpan = {
        name: options.name,
        kind: options.kind,
        input: options.input,
        attributes: { ...options.attributes },
        events: [],
        children: [],
      };
      (stack.at(-1)?.children ?? roots).push(recorded);
      const handle: PipelineSpan = {
        setAttributes: (attributes) => Object.assign(recorded.attributes, attributes),
        addEvent: (name, attributes) =>
          recorded.events.push({ name, attributes: attributes && { ...attributes } }),
      };
      stack.push(recorded);
      try {
        return await fn(handle);
      } finally {
        stack.pop();
      }
    },
  };
  return { tracer, roots };
}

export function flattenSpans(spans: readonly RecordedSpan[]): RecordedSpan[] {
  return spans.flatMap((s) => [s, ...flattenSpans(s.children)]);
}

export interface SpyProviderOptions {
  // Rewrites the enrich result before the pipeline sees it.
  readonly enrichResult?: (
    result: ProviderResult<readonly RawCompany[]>,
  ) => ProviderResult<readonly RawCompany[]>;
}

// Wraps a provider and records every call's arguments.
export class SpyProvider implements CompanyProvider {
  readonly autocompleteCalls: string[] = [];
  readonly searchCalls: { filters: SearchFilters; limit: number }[] = [];
  readonly enrichCalls: (readonly string[])[] = [];
  private readonly inner: CompanyProvider;
  private readonly options: SpyProviderOptions;

  constructor(inner: CompanyProvider, options: SpyProviderOptions = {}) {
    this.inner = inner;
    this.options = options;
  }

  autocompleteIndustry(query: string) {
    this.autocompleteCalls.push(query);
    return this.inner.autocompleteIndustry(query);
  }

  searchCompanies(filters: SearchFilters, limit: number) {
    this.searchCalls.push({ filters, limit });
    return this.inner.searchCompanies(filters, limit);
  }

  async enrichCompanies(linkedin_urls: readonly string[]) {
    this.enrichCalls.push(linkedin_urls);
    const result = await this.inner.enrichCompanies(linkedin_urls);
    return this.options.enrichResult ? this.options.enrichResult(result) : result;
  }
}

export interface Harness {
  readonly fixture: FixtureProvider;
  readonly provider: SpyProvider;
  readonly llm: FakeLlmClient;
  readonly roots: RecordedSpan[];
  readonly deps: PipelineDeps;
}

// One run's worth of collaborators. The fixture provider's caps come from
// `providerConfig` (default: the pipeline config), so tests can make the
// provider's BudgetGuard stricter than the pipeline's own limits.
export function harness(
  config: RunConfig,
  options: {
    readonly fixture?: Omit<FixtureProviderOptions, "config">;
    readonly providerConfig?: Pick<RunConfig, "max_search_results" | "max_enrichments">;
    readonly spy?: SpyProviderOptions;
    readonly llm?: FakeLlmClientOptions;
  } = {},
): Harness {
  const fixture = new FixtureProvider({
    config: options.providerConfig ?? config,
    ...options.fixture,
  });
  const provider = new SpyProvider(fixture, options.spy);
  const llm = new FakeLlmClient(options.llm);
  const { tracer, roots } = createRecordingTracer();
  let clock = 0;
  return {
    fixture,
    provider,
    llm,
    roots,
    deps: {
      provider,
      budget: fixture.budget,
      llm,
      tracer,
      trace_id: "trace-test",
      now: () => (clock += 1),
    },
  };
}

import { describe, expect, it } from "vitest";
import { defaultFakeAssessment } from "../../src/core/agent/fake-llm";
import type { LlmClient } from "../../src/core/agent/llm";
import { runBaselinePipeline } from "../../src/core/agent/pipeline";
import type { BaselineProspect } from "../../src/core/agent/types";
import { DEV_RUN_CONFIG, type RunConfig } from "../../src/core/types";
import { OPEN_ICP, flattenSpans, harness, icp } from "./helpers";

const ids = (prospects: readonly BaselineProspect[]) =>
  prospects.map((p) => p.raw.crustdata_company_id);

const enrichmentStatuses = (prospects: readonly BaselineProspect[]) =>
  Object.fromEntries(prospects.map((p) => [p.raw.crustdata_company_id, p.enrichment.status]));

const config = (overrides: Partial<RunConfig> = {}): RunConfig => ({
  ...DEV_RUN_CONFIG,
  ...overrides,
});

describe("runBaselinePipeline: successful run", () => {
  it("searches, enriches in search order within DEV limits, and assesses every company", async () => {
    const h = harness(config({ model: "model-from-run-config" }), { fixture: { cost_usd: 0.25 } });
    const result = await runBaselinePipeline(OPEN_ICP, h.deps, {
      config: config({ model: "model-from-run-config" }),
    });

    expect(result.status).toBe("completed");
    expect(ids(result.prospects)).toEqual([1001, 1002, 1003, 1004, 1005, 1006, 1007, 1008, 1009, 1010]);

    // DEV_RUN_CONFIG allows 2 enrichments: the first two companies with a LinkedIn URL.
    expect(h.provider.enrichCalls).toHaveLength(1);
    expect(h.provider.enrichCalls[0]).toHaveLength(DEV_RUN_CONFIG.max_enrichments);
    expect(enrichmentStatuses(result.prospects)).toEqual({
      1001: "enriched",
      1002: "enriched",
      1003: "skipped_budget",
      1004: "skipped_budget",
      1005: "skipped_budget",
      1006: "skipped_budget",
      1007: "skipped_budget",
      1008: "skipped_budget",
      1009: "skipped_budget",
      1010: "skipped_no_linkedin",
    });
    // Enriched records replace their search records.
    expect(result.prospects[0].raw.source).toBe("enrich");
    expect(result.prospects[2].raw.source).toBe("search");

    // Outreach drafts come back as part of each assessment.
    for (const p of result.prospects) {
      expect(p.assessment.status).toBe("assessed");
      if (p.assessment.status === "assessed") {
        expect(p.assessment.assessment.outreach?.body).toContain(String(p.raw.crustdata_company_id));
      }
    }

    expect(result.run).toMatchObject({
      trace_id: "trace-test",
      counts: {
        searched: 10,
        enriched: 2,
        delivered: 10,
        llm_calls: 10,
        llm_input_tokens: 1000,
        llm_output_tokens: 500,
      },
      cost_usd_by_step: { plan: 0, search: 0.25, validate: 0, enrich: 0.25, assess: 0 },
    });
    expect(result.run.timings_ms_by_step.validate).toBe(0);
    expect(result.run.timings_ms_by_step.assess).toBeGreaterThan(0);
    expect(result.usage.provider).toEqual({ cost_usd: 0.5, searched: 10, enriched: 2 });
    expect(result.issues).toEqual([]);
  });

  it("reads the model and output-token limit from RunConfig", async () => {
    const runConfig = config({ model: "gateway/some-model", max_output_tokens_per_call: 321 });
    const h = harness(runConfig);
    await runBaselinePipeline(OPEN_ICP, h.deps, { config: runConfig });

    expect(h.llm.requests).toHaveLength(10);
    for (const request of h.llm.requests) {
      expect(request.model).toBe("gateway/some-model");
      expect(request.max_output_tokens).toBe(321);
    }
  });

  it("never runs model calls in parallel", async () => {
    const h = harness(config(), { llm: { delay_ms: 2 } });
    await runBaselinePipeline(OPEN_ICP, h.deps, { config: config() });
    expect(h.llm.requests).toHaveLength(10);
    expect(h.llm.max_in_flight).toBe(1);
  });

  it("can limit assessment to enriched companies", async () => {
    const h = harness(config());
    const result = await runBaselinePipeline(OPEN_ICP, h.deps, {
      config: config(),
      assess: "enriched_only",
    });
    expect(h.llm.requests).toHaveLength(2);
    expect(result.prospects.filter((p) => p.assessment.status === "not_assessed")).toHaveLength(8);
  });

  it("emits a span tree through the tracer", async () => {
    const h = harness(config());
    await runBaselinePipeline(OPEN_ICP, h.deps, { config: config() });

    expect(h.roots).toHaveLength(1);
    const root = h.roots[0];
    expect(root.name).toBe("signalscout_baseline_run");
    expect(root.kind).toBe("WORKFLOW");
    expect(root.attributes).toMatchObject({
      "signalscout.trace_id": "trace-test",
      "signalscout.status": "completed",
      "signalscout.llm_calls": 10,
    });
    expect(root.children.map((s) => s.name)).toEqual(["plan", "search", "enrich", "assess"]);
    const llmSpans = flattenSpans(h.roots).filter((s) => s.kind === "LLM");
    expect(llmSpans).toHaveLength(10);
    expect(llmSpans[0].attributes["llm.model"]).toBe(DEV_RUN_CONFIG.model);
  });
});

describe("runBaselinePipeline: ICP to SearchFilters", () => {
  it("maps free-text industry to provider labels with autocomplete", async () => {
    const h = harness(config());
    const result = await runBaselinePipeline(icp({ industry: "soft" }), h.deps, { config: config() });

    expect(h.provider.autocompleteCalls).toEqual(["soft"]);
    expect(result.filters.industries).toEqual(["Software"]);
