8	export class OpenAiCompatibleLlmClient implements LlmClient {
9	  private readonly client: Pick<OpenAI, "chat">;
10	
11	  constructor(client: Pick<OpenAI, "chat">) {
12	    this.client = client;
13	  }
14	
15	  async complete(request: LlmRequest): Promise<LlmResponse> {
16	    try {
17	      const completion = await this.client.chat.completions.create({
18	        model: request.model,
19	        messages: request.messages.map((m) => ({
20	          role: m.role,
21	          content: m.content,
22	        })),
23	        // max_tokens rather than max_completion_tokens: it is the parameter
24	        // OpenAI-compatible gateways accept most widely.
25	        max_tokens: request.max_output_tokens,
26	      });
27	      const choice = completion.choices[0];
28	      return {
29	        ok: true,
30	        text: choice?.message.content ?? "",
31	        input_tokens: completion.usage?.prompt_tokens ?? 0,
32	        output_tokens: completion.usage?.completion_tokens ?? 0,
33	        truncated: choice?.finish_reason === "length",
34	      };
35	    } catch (err) {
36	      return {
37	        ok: false,
38	        error: { message: err instanceof Error ? err.message : String(err) },
