1	// Naive baseline pipeline: plan -> search -> enrich -> assess. It deliberately
2	// skips validation, deduplication, buildFacts(), validateAssessment() and
3	// checkClaims(), so its trace shows what the unguarded agent does.
4	// No network of its own: data comes from the CompanyProvider and model output
5	// from the LlmClient passed in.
6	
7	import type { SearchFilters } from "../data/provider";
8	import { DEV_RUN_CONFIG, type RawCompany } from "../types";
9	import { buildAssessmentMessages, parseAssessment } from "./assess";
10	import { enrichInSearchOrder } from "./enrich";
11	import { assessmentCriteria, buildSearchFilters, describeIcp } from "./icp";
12	import type { LlmResponse } from "./llm";
13	import { RunRecorder } from "./recorder";
14	import { noopTracer } from "./tracer";
15	import type {
16	  AssessmentOutcome,
17	  BaselineProspect,
18	  EnrichmentOutcome,
19	  IcpInput,
20	  PipelineDeps,
21	  PipelineIssue,
22	  PipelineOptions,
23	  PipelineResult,
24	  PipelineStatus,
25	} from "./types";
26	
27	type SearchOutcome =
28	  | { readonly kind: "found"; readonly companies: readonly RawCompany[] }
29	  | { readonly kind: "empty" }
30	  | { readonly kind: "stopped" };
31	
32	export async function runBaselinePipeline(
33	  icp: IcpInput,
34	  deps: PipelineDeps,
35	  options: PipelineOptions = {},
36	): Promise<PipelineResult> {
37	  const config = options.config ?? DEV_RUN_CONFIG;
38	  const assessScope = options.assess ?? "all_searched";
39	  const tracer = deps.tracer ?? noopTracer;
40	  const trace_id = deps.trace_id ?? crypto.randomUUID();
41	  const recorder = new RunRecorder(deps.now ?? Date.now);
42	  const input_description = describeIcp(icp);
43	  const issues: PipelineIssue[] = [];
44	
45	  return tracer.span(
46	    {
47	      name: "signalscout_baseline_run",
48	      kind: "WORKFLOW",
49	      input: { trace_id, icp },
50	      attributes: {
51	        "signalscout.trace_id": trace_id,
52	        "signalscout.pipeline": "naive_baseline",
53	        "signalscout.model": config.model,
54	        "signalscout.max_search_results": config.max_search_results,
55	        "signalscout.max_enrichments": config.max_enrichments,
56	        "signalscout.max_llm_calls_per_run": config.max_llm_calls_per_run,
57	        "signalscout.max_output_tokens_per_call": config.max_output_tokens_per_call,
58	      },
59	    },
60	    async (root) => {
61	      const finish = (
62	        status: PipelineStatus,
63	        filters: SearchFilters,
64	        prospects: readonly BaselineProspect[],
65	      ): PipelineResult => {
66	        recorder.counts.delivered = prospects.length;
67	        const run = recorder.build(trace_id, input_description, config);
68	        const provider = deps.budget.snapshot();
69	        root.setAttributes({
70	          "signalscout.status": status,
71	          "signalscout.searched": run.counts.searched,
72	          "signalscout.enriched": run.counts.enriched,
73	          "signalscout.delivered": run.counts.delivered,
74	          "signalscout.llm_calls": run.counts.llm_calls,
75	          "signalscout.provider_cost_usd": provider.cost_usd,
76	          "signalscout.issue_codes": issues.map((i) => i.code),
77	        });
78	        return {
79	          status,
80	          run,
81	          filters,
82	          prospects,
83	          issues,
84	          usage: {
85	            provider,
86	            max_search_results: config.max_search_results,
87	            max_enrichments: config.max_enrichments,
88	            llm_calls: run.counts.llm_calls,
89	            max_llm_calls_per_run: config.max_llm_calls_per_run,
90	          },
91	        };
92	      };
93	
94	      // 1. Plan: ICP -> SearchFilters (free industry autocomplete).
95	      const plan = await recorder.time("plan", () =>
96	        tracer.span({ name: "plan", kind: "CHAIN", input: icp }, async (span) => {
97	          const result = await buildSearchFilters(icp, deps.provider);
98	          span.setAttributes({
99	            "search.industries": result.filters.industries,
100	            "search.country": result.filters.country,
101	            "search.employee_count_ranges": result.filters.employee_count_ranges,
102	          });
103	          return result;
104	        }),
105	      );
106	      recorder.addCost("plan", plan.cost_usd);
107	      issues.push(...plan.issues);
108	      const filters = plan.filters;
109	
110	      // 2. Search.
111	      const search = await recorder.time("search", () =>
112	        tracer.span(
113	          { name: "search", kind: "TOOL", input: filters },
114	          async (span): Promise<SearchOutcome> => {
115	            const limit = config.max_search_results - deps.budget.snapshot().searched;
116	            if (limit <= 0) {
117	              issues.push({
118	                step: "search",
119	                code: "search_budget_exhausted",
120	                message: "No search results left in this run's budget.",
121	              });
122	              span.setAttributes({ "provider.outcome": "budget_exhausted" });
123	              return { kind: "stopped" };
124	            }
125	            const result = await deps.provider.searchCompanies(filters, limit);
126	            if (result.ok) {
127	              recorder.addCost("search", result.cost_usd);
128	              recorder.counts.searched = result.data.length;
129	              span.setAttributes({
130	                "provider.outcome": "ok",
131	                "provider.limit": limit,
132	                "provider.returned": result.data.length,
133	                "provider.cost_usd": result.cost_usd,
134	                "provider.calls": result.calls,
135	              });
136	              return { kind: "found", companies: result.data };
137	            }
138	            const category = result.error.category;
139	            span.setAttributes({ "provider.outcome": category, "provider.limit": limit });
140	            if (category === "no_match") {
141	              issues.push({
142	                step: "search",
143	                code: "search_no_match",
144	                message: "No companies match the search filters.",
145	                error_category: category,
146	              });
147	              return { kind: "empty" };
148	            }
149	            issues.push({
150	              step: "search",
151	              code: category === "budget_cap_reached" ? "search_budget_exhausted" : "search_failed",
152	              message: `Search failed with ${category}: ${result.error.message}`,
