154	            });
155	            return { kind: "stopped" };
156	          },
157	        ),
158	      );
159	      if (search.kind === "stopped") return finish("stopped", filters, []);
160	      if (search.kind === "empty") return finish("completed_empty", filters, []);
161	      const companies = search.companies;
162	
163	      // 3. Enrich in search order, within the remaining enrichment budget.
164	      const enrich = await recorder.time("enrich", () =>
165	        tracer.span(
166	          {
167	            name: "enrich",
168	            kind: "TOOL",
169	            input: { companies: companies.map((c) => c.crustdata_company_id) },
170	          },
171	          async (span) => {
172	            const remaining = config.max_enrichments - deps.budget.snapshot().enriched;
173	            const result = await enrichInSearchOrder(companies, deps.provider, remaining);
174	            const statusCount = (status: EnrichmentOutcome["status"]) =>
175	              result.outcomes.filter((o) => o.status === status).length;
176	            span.setAttributes({
177	              "enrich.remaining_before": Math.max(0, remaining),
178	              "enrich.requested": result.requested,
179	              "enrich.enriched": statusCount("enriched"),
180	              "enrich.not_returned": statusCount("not_returned"),
181	              "enrich.skipped_budget": statusCount("skipped_budget"),
182	              "enrich.skipped_no_linkedin": statusCount("skipped_no_linkedin"),
183	              "enrich.failed": statusCount("failed"),
184	              "provider.cost_usd": result.cost_usd,
185	            });
186	            return result;
187	          },
188	        ),
189	      );
190	      recorder.addCost("enrich", enrich.cost_usd);
191	      recorder.counts.enriched = enrich.enriched.size;
192	      issues.push(...enrich.issues);
193	
194	      const pending = companies.map((company, i) => ({
195	        raw: enrich.enriched.get(i) ?? company,
196	        enrichment: enrich.outcomes[i],
197	      }));
198	
199	      // 4. Assess, one company at a time, within the model-call cap.
200	      const criteria = assessmentCriteria(icp);
201	      const prospects = await recorder.time("assess", () =>
202	        tracer.span(
203	          { name: "assess", kind: "AGENT", input: { companies: pending.length, criteria } },
204	          async (span) => {
205	            const out: BaselineProspect[] = [];
206	            let capReached = false;
207	            // Sequential on purpose: no parallel model calls.
208	            for (const prospect of pending) {
209	              if (assessScope === "enriched_only" && prospect.enrichment.status !== "enriched") {
210	                out.push({ ...prospect, assessment: { status: "not_assessed", reason: "not_enriched" } });
