216	                continue;
217	              }
218	              const assessment = await assessOne(prospect);
219	              out.push({ ...prospect, assessment });
220	            }
221	            if (capReached) {
222	              issues.push({
223	                step: "assess",
224	                code: "llm_call_cap_reached",
225	                message: `Stopped assessing after ${config.max_llm_calls_per_run} model calls.`,
226	              });
227	            }
228	            span.setAttributes({
229	              "llm.calls": recorder.counts.llm_calls,
230	              "llm.input_tokens": recorder.counts.llm_input_tokens,
231	              "llm.output_tokens": recorder.counts.llm_output_tokens,
232	              "assess.assessed": out.filter((p) => p.assessment.status === "assessed").length,
233	              "assess.failed": out.filter((p) => p.assessment.status === "failed").length,
234	              "assess.not_assessed": out.filter((p) => p.assessment.status === "not_assessed").length,
235	            });
236	            return out;
237	          },
238	        ),
239	      );
240	
241	      return finish("completed", filters, prospects);
242	
243	      async function assessOne(
244	        prospect: Pick<BaselineProspect, "raw" | "enrichment">,
245	      ): Promise<AssessmentOutcome> {
246	        const messages = buildAssessmentMessages(input_description, criteria, icp, prospect);
247	        return tracer.span(
248	          {
249	            name: "assess_company",
250	            kind: "LLM",
251	            input: messages,
252	            attributes: {
253	              "company.id": prospect.raw.crustdata_company_id,
254	              "company.enrichment_status": prospect.enrichment.status,
255	              "llm.model": config.model,
256	              "llm.max_output_tokens": config.max_output_tokens_per_call,
257	            },
258	          },
259	          async (span) => {
260	            recorder.counts.llm_calls += 1;
261	            let response: LlmResponse;
