// Model-call policy constants for the agent. Reviewed values live here, not
// scattered through the adapter. None of these are spending limits: the
// per-run model spend cap and the shared-key spend threshold are not yet
// agreed and belong in the shared RunConfig.

// Shared LiteLLM gateway (OpenAI-compatible). Callers may override it.
export const LITELLM_GATEWAY_BASE_URL = "https://litellm.vision.aivar.app/v1";

// Every model request is deterministic-as-possible.
export const LLM_TEMPERATURE = 0;

// Per HTTP attempt. The OpenAI SDK default is 10 minutes.
export const LLM_REQUEST_TIMEOUT_MS = 30_000;

// Retries after the first attempt, for rate-limit responses only. The SDK's
// own retries are disabled (maxRetries: 0) so these are the only ones.
export const LLM_MAX_RETRIES = 2;

// Wait before retry n (1-based) when the gateway sends no usable Retry-After.
export const LLM_RETRY_BACKOFF_MS: readonly number[] = [1_000, 2_000];

// Longest single wait we will honour. A longer Retry-After ends the call as
// rate_limited instead of retrying early.
export const LLM_MAX_RETRY_WAIT_MS = 10_000;

// Wall-clock budget for one logical model call, including retries and waits.
// Each attempt's timeout is clipped to what is left of it.
export const LLM_CALL_DEADLINE_MS = 60_000;

// Rough fallback rates documented by Abhijit, used only when the gateway
// does not report a cost. Results are labelled "estimated", never measured.
export const ESTIMATED_INPUT_USD_PER_MILLION_TOKENS = 1.1;
export const ESTIMATED_OUTPUT_USD_PER_MILLION_TOKENS = 5.5;

// Model cost accounting. A cost is either reported by the LiteLLM gateway,
// estimated from token usage at the fallback rates, or unavailable. A missing
// cost is never reported as $0.

import {
  ESTIMATED_INPUT_USD_PER_MILLION_TOKENS,
  ESTIMATED_OUTPUT_USD_PER_MILLION_TOKENS,
} from "./llm-policy";

export type LlmCost =
  | { readonly basis: "gateway_reported"; readonly usd: number }
  | {
      readonly basis: "estimated";
      readonly usd: number;
      readonly input_usd_per_million_tokens: number;
      readonly output_usd_per_million_tokens: number;
    }
  | { readonly basis: "unavailable" };

export type LlmCostBasis = LlmCost["basis"];

export interface LlmTokenUsage {
  readonly prompt_tokens: number;
  readonly completion_tokens: number;
}

// Spend reported by the gateway for the shared API key, when it sends it.
export interface LlmKeySpend {
  readonly spend_usd?: number;
  readonly max_budget_usd?: number;
}

export const LITELLM_RESPONSE_COST_HEADER = "x-litellm-response-cost";
export const LITELLM_KEY_SPEND_HEADER = "x-litellm-key-spend";
export const LITELLM_KEY_MAX_BUDGET_HEADER = "x-litellm-key-max-budget";

// A header value as a finite, non-negative number, else undefined.
export function parseNonNegativeNumber(value: string | null | undefined): number | undefined {
  if (value === null || value === undefined) return undefined;
  const text = value.trim();
  if (text === "") return undefined;
  const n = Number(text);
  return Number.isFinite(n) && n >= 0 ? n : undefined;
}

export function readGatewayCost(headers: Headers | undefined): number | undefined {
  return parseNonNegativeNumber(headers?.get(LITELLM_RESPONSE_COST_HEADER));
}

export function readKeySpend(headers: Headers | undefined): LlmKeySpend | undefined {
  const spend_usd = parseNonNegativeNumber(headers?.get(LITELLM_KEY_SPEND_HEADER));
  const max_budget_usd = parseNonNegativeNumber(headers?.get(LITELLM_KEY_MAX_BUDGET_HEADER));
  if (spend_usd === undefined && max_budget_usd === undefined) return undefined;
  return {
    ...(spend_usd !== undefined ? { spend_usd } : {}),
    ...(max_budget_usd !== undefined ? { max_budget_usd } : {}),
  };
}

function isTokenCount(n: unknown): n is number {
  return typeof n === "number" && Number.isFinite(n) && n >= 0;
}

// Token usage only when both counts are present and sane.
export function completeUsage(
  prompt_tokens: unknown,
  completion_tokens: unknown,
): LlmTokenUsage | undefined {
  return isTokenCount(prompt_tokens) && isTokenCount(completion_tokens)
    ? { prompt_tokens, completion_tokens }
    : undefined;
}

export function estimateCostUsd(usage: LlmTokenUsage): number {
  return (
    (usage.prompt_tokens / 1_000_000) * ESTIMATED_INPUT_USD_PER_MILLION_TOKENS +
    (usage.completion_tokens / 1_000_000) * ESTIMATED_OUTPUT_USD_PER_MILLION_TOKENS
  );
}

// Gateway cost first, then an estimate from usage, else unavailable.
export function resolveLlmCost(
  gateway_cost_usd: number | undefined,
  usage: LlmTokenUsage | undefined,
): LlmCost {
  if (gateway_cost_usd !== undefined) {
    return { basis: "gateway_reported", usd: gateway_cost_usd };
  }
  if (usage) {
    return {
      basis: "estimated",
      usd: estimateCostUsd(usage),
      input_usd_per_million_tokens: ESTIMATED_INPUT_USD_PER_MILLION_TOKENS,
      output_usd_per_million_tokens: ESTIMATED_OUTPUT_USD_PER_MILLION_TOKENS,
    };
  }
  return { basis: "unavailable" };
}

// Model access for the agent. The pipeline only talks to LlmClient; the real
// adapter lives in openai-llm.ts (built by gateway-client.ts) and tests use
// fake-llm.ts. Like providers, clients return errors instead of throwing.

import type { LlmCost, LlmKeySpend, LlmTokenUsage } from "./llm-cost";

export interface LlmMessage {
  readonly role: "system" | "user";
  readonly content: string;
}

export interface LlmRequest {
  // Always RunConfig.model; never hardcoded by a client.
  readonly model: string;
  readonly messages: readonly LlmMessage[];
  // Always RunConfig.max_output_tokens_per_call.
  readonly max_output_tokens: number;
  // Always LLM_TEMPERATURE (0).
  readonly temperature: number;
}

// Why a model call failed.
export type LlmErrorCategory =
  | "rate_limited" // 429, after any allowed retries
  | "timeout" // an attempt timed out, or the call ran out of time
  | "auth_failed" // 401 / 403
  | "provider_unavailable" // 5xx or no connection
  | "malformed_response" // a 2xx response without a usable completion
  | "model_error"; // anything else, e.g. 400 / 404 / 422

// Where the response headers were read from: withResponse() on an unwrapped
// SDK promise, the fetch hook (needed once wrapOpenAI has wrapped the
// client), or nowhere.
export type LlmHeaderSource = "with_response" | "fetch_hook" | "none";

// Facts about one logical model call, success or failure. Secrets never
// appear here.
export interface LlmCallMeta {
  readonly model: string;
  // HTTP requests made for this logical call: 1 plus retries.
  readonly attempts: number;
  // Milliseconds waited before each retry.
  readonly retry_waits_ms: readonly number[];
  // Absent when the response did not report both token counts.
  readonly usage?: LlmTokenUsage;
  readonly cost: LlmCost;
  readonly key_spend?: LlmKeySpend;
  readonly header_source: LlmHeaderSource;
}

export interface LlmError {
  readonly category: LlmErrorCategory;
  // Redacted: never contains an API key or Authorization header.
  readonly message: string;
  readonly status?: number;
}

export type LlmResponse =
  | {
      readonly ok: true;
      readonly text: string;
      // True when the model stopped because it hit max_output_tokens.
      readonly truncated: boolean;
      readonly meta: LlmCallMeta;
    }
  | { readonly ok: false; readonly error: LlmError; readonly meta: LlmCallMeta };

export interface LlmClient {
  // True when the client records its own LLM spans (e.g. via wrapOpenAI), so
  // the pipeline must not record the prompt and completion a second time.
  readonly records_llm_spans: boolean;
  complete(request: LlmRequest): Promise<LlmResponse>;
}

