  known_usd: number;
  calls_by_basis: Record<LlmCostBasis, number>;
  latest_key_spend?: LlmKeySpend;
} = {
  gateway_reported_usd: 0,
  estimated_usd: 0,
  known_usd: 0,
  calls_by_basis: { gateway_reported: 0, estimated: 0, unavailable: 0 },
};

